def rk(f,a,b,y0,N=1200):
 h=(b-a)/N;x=a;y=y0;pts=[(x,y)]
 for i in range(N):
  try:
   k1=f(x,y);k2=f(x+h/2,y+h*k1/2);k3=f(x+h/2,y+h*k2/2);k4=f(x+h,y+h*k3)
   y+=h*(k1+2*k2+2*k3+k4)/6;x=a+(i+1)*h
   if not math.isfinite(y) or abs(y)>1000:break
   pts.append((x,y))
  except (ValueError,OverflowError,ZeroDivisionError):break
 return pts
def both(f,lo,hi,y=0,x0=0):return list(reversed(rk(f,x0,lo,y)))+rk(f,x0,hi,y)[1:]
def sampled(f,a,b,N=500):return [(a+(b-a)*i/N,f(a+(b-a)*i/N)) for i in range(N+1)]
def euler(f,x,y,h,n):
 pts=[(x,y)]
 for i in range(n):y+=h*f(x,y);x=pts[0][0]+(i+1)*h;pts.append((x,y))
 return pts
