add(19,M(r"y'=y,\ y(0)=1")+'에서 (a) '+M(r'h=0.4,0.2,0.1')+'로 '+M(r'y(0.4)')+'를 근사하라. (b) 지수함수와 오일러 다각선을 그려 과대·과소 여부를 설명하라. (c) 오차와 반분 효과를 구하라.','For '+M(r"y'=y,\ y(0)=1")+', (a) approximate '+M(r'y(0.4)')+' with '+M(r'h=0.4,0.2,0.1')+'. (b) Plot the exponential and Euler polygons and classify bias. (c) Compute errors and the effect of halving the step.',[(M(r'y_{n+1}=(1+h)y_n,\ y_n=(1+h)^n')+'이므로 마지막 값을 계산한다.',M(r'y_{n+1}=(1+h)y_n,\ y_n=(1+h)^n')+' gives each endpoint.'),('정확해는 위로 볼록하여 접선 다각선이 아래에 놓인다. '+M(r'e^{0.4}\approx1.491824698')+'.','The exact solution is convex, placing tangent polygons below it. '+M(r'e^{0.4}\approx1.491824698')+'.')],M(r'y_E=1.4,1.44,1.4641;\quad E=0.091824698,0.051824698,0.027724698')+'; 모두 과소이며 오차는 점차 약 절반이 된다.',M(r'y_E=1.4,1.44,1.4641;\quad E=0.091824698,0.051824698,0.027724698')+'; all underestimate, with errors approaching a factor-of-two reduction.','점화식을 반복한 값과 거듭제곱 공식을 독립 대조했다.','Repeated updates were checked against the power formula.','abc')
svg(19,'Euler polygons vs exp(x)',None,(0,.4),(1,1.5),[('exact exp(x)',sampled(math.exp,0,.4))]+[(f'h={h}',p) for h,p in zip([.4,.2,.1],vals)])
add(20,'원문 방향장은 각 수평 줄의 기울기가 양수이며 높이가 커질수록 완만해진다. 원점을 지나는 해의 오일러 다각선을 '+M(r'h=1,0.5')+'로 그리고 과대·과소 여부를 설명하라.','The source field has positive slopes constant along horizontal rows, becoming shallower at greater heights. Sketch Euler polygons from the origin with '+M(r'h=1,0.5')+' and classify their bias.', [('초기 선분의 기울기를 읽어 첫 단계를 그리고 새 끝점에서의 선분 기울기로 다음 단계를 연결한다. 원문 그림에 식이 없으므로 수치는 그래프에서 읽는 근사값이다.','Read the initial slope, take one step, then use the slope at the new endpoint. Since no formula is supplied, coordinates are graphical approximations.'),('높이가 증가할수록 기울기가 작아져 실제 해는 아래로 오목하다. 접선으로 진행하는 오일러 다각선은 해보다 높다.','The slope decreases as the solution rises, so the curve is concave down. Forward tangent steps lie above the solution.')],'두 간격 모두 과대근사. 간격을 반으로 줄이면 다각선이 해에 더 가까워진다.','Both step sizes overestimate; the half-step polygon lies closer to the solution.','자체 그림은 같은 방향장 특성을 갖는 대표 모델을 사용한 개형이며 원문에 없는 정확한 식을 주장하지 않는다.','The original figure uses a representative model with the same field properties, without claiming an unspecified exact source equation.')
svg(20,'Schematic field: y prime = 1/(1+y); graphical estimates',lambda x,y:1/(1+y),(0,2),(0,2),[('representative exact curve',sampled(lambda x:math.sqrt(1+2*x)-1,0,2)),('Euler h=1',euler(lambda x,y:1/(1+y),0,0,1,2)),('Euler h=0.5',euler(lambda x,y:1/(1+y),0,0,.5,4))])
for n,eq,f,x0,y0,h,N,target in [(21,r'y-2x',lambda x,y:y-2*x,1,0,.5,4,'y_1,y_2,y_3,y_4'),(22,r'x^2y-\tfrac12y^2',lambda x,y:x*x*y-.5*y*y,0,1,.2,5,'y(1)'),(23,r'y+xy',lambda x,y:y+x*y,0,1,.1,5,'y(0.5)')]:
 pts=euler(f,x0,y0,h,N);table=r'\begin{array}{c|r}x_n&y_n\\'+r'\\'.join(f'{x:.2f}&{y:.9f}' for x,y in pts)+r'\end{array}'
 ans=','.join(f'{p[1]:.9f}' for p in pts[1:]) if n==21 else rf'{target}\approx{pts[-1][1]:.9f}'
 add(n,M("y'="+eq+rf',\ y({x0})={y0},\ h={h}')+'에서 오일러 방법으로 '+M(target)+'을 구하라.','Use Euler’s method for '+M("y'="+eq+rf',\ y({x0})={y0},\ h={h}')+' to estimate '+M(target)+'.',[(M(r'x_{n+1}=x_n+h,\quad y_{n+1}=y_n+hf(x_n,y_n)')+'을 반복한다.',M(r'x_{n+1}=x_n+h,\quad y_{n+1}=y_n+hf(x_n,y_n)')+' is iterated.'),(M(table),M(table))],M(ans),M(ans),'중간값을 반올림하지 않고 마지막 표시만 반올림했다.','Intermediate values retain full precision; only displayed results are rounded.')
pts24=[euler(lambda x,y:math.cos(x+y),0,0,h,round(.6/h)) for h in [.2,.1]]
add(24,M(r"y'=\cos(x+y),\ y(0)=0")+'에서 '+M(r'y(0.6)')+'을 (a) '+M(r'h=0.2')+', (b) '+M(r'h=0.1')+'로 근사하라.','Estimate '+M(r'y(0.6)')+' for '+M(r"y'=\cos(x+y),\ y(0)=0")+' using (a) '+M(r'h=0.2')+' and (b) '+M(r'h=0.1')+'.',[(M(r'y_{n+1}=y_n+h\cos(x_n+y_n)')+'을 각 간격으로 반복한다.',M(r'y_{n+1}=y_n+h\cos(x_n+y_n)')+' is iterated for each step size.'),('각각 세 번과 여섯 번 갱신한다.','Use three and six updates, respectively.')],M(rf'\text{{(a) }}{pts24[0][-1][1]:.9f};\quad\text{{(b) }}{pts24[1][-1][1]:.9f}'),M(rf'\text{{(a) }}{pts24[0][-1][1]:.9f};\quad\text{{(b) }}{pts24[1][-1][1]:.9f}'),'정확해 '+M(r'y=2\arctan x-x')+'와 비교하면 간격 축소로 오차가 줄어든다.','Comparison with the exact solution '+M(r'y=2\arctan x-x')+' confirms improved accuracy for the smaller step.','ab')
hs=[1,.1,.01,.001];vs=[euler(lambda x,y:3*x*x*(2-y),0,3,h,round(1/h))[-1][1] for h in hs];exact=2+math.exp(-1)
table=r'\begin{array}{c|r|r}h&y_E&y_{exact}-y_E\\'+r'\\'.join(f'{h}&{v:.9f}&{exact-v:.9f}' for h,v in zip(hs,vs))+r'\end{array}'
add(25,M(r"y'+3x^2y=6x^2,\ y(0)=3")+'에서 (a) '+M(r'h=1,0.1,0.01,0.001')+'로 '+M(r'y(1)')+'을 계산하라. (b) '+M(r'y=2+e^{-x^3}')+'을 검증하고 (c) 오차의 변화를 비교하라.','For '+M(r"y'+3x^2y=6x^2,\ y(0)=3")+', (a) compute '+M(r'y(1)')+' with '+M(r'h=1,0.1,0.01,0.001')+'. (b) Verify '+M(r'y=2+e^{-x^3}')+' and (c) compare errors.',[(M(r'y_{n+1}=y_n+3hx_n^2(2-y_n)')+'으로 반복한다.',M(r'y_{n+1}=y_n+3hx_n^2(2-y_n)')+' is iterated.'),(M(r'y^{\prime}=-3x^2e^{-x^3},\quad y^{\prime}+3x^2y=6x^2,\quad y(0)=3')+'.',M(r'y^{\prime}=-3x^2e^{-x^3},\quad y^{\prime}+3x^2y=6x^2,\quad y(0)=3')+'.')],M(table)+'; 작은 간격에서는 열 배 축소할 때 오차 크기도 약 열 배 작아진다.',M(table)+'; for small steps, dividing the step by ten reduces the error magnitude by about ten.','음의 부호는 과대근사임을 뜻한다. 첫 거친 간격은 점근적 오차비에서 제외해야 한다.','Negative signed errors indicate overestimation. The coarsest step need not follow the asymptotic error ratio.','abc')
f26=lambda x,y:x**3-y**3;v26=euler(f26,0,1,.01,200)[-1][1];ref=rk(f26,0,2,1,4000)[-1][1]
add(26,M(r"y'=x^3-y^3,\ y(0)=1")+'에서 (a) '+M(r'h=0.01')+'로 '+M(r'y(2)')+'를 근사하고 (b) 컴퓨터 해곡선과 비교하라.','For '+M(r"y'=x^3-y^3,\ y(0)=1")+', (a) estimate '+M(r'y(2)')+' using '+M(r'h=0.01')+' and (b) compare with a computed solution curve.',[(M(r'y_{n+1}=y_n+0.01(x_n^3-y_n^3)')+'을 이백 번 반복한다.',M(r'y_{n+1}=y_n+0.01(x_n^3-y_n^3)')+' is iterated two hundred times.'),('참조 곡선은 더 작은 간격의 4차 방법으로 계산한다.','Compute a reference curve using a finer fourth-order method.')],M(rf'y_E(2)\approx{v26:.9f};\quad y_{{RK4}}(2)\approx{ref:.9f};\quad E\approx{ref-v26:.9f}'),M(rf'y_E(2)\approx{v26:.9f};\quad y_{{RK4}}(2)\approx{ref:.9f};\quad E\approx{ref-v26:.9f}'),'참조 계산의 간격을 반으로 줄여 표시된 자릿수의 안정성을 확인했다.','Halving the reference step confirms stability of the displayed digits.','ab')
svg(26,'Euler h=0.01 and fine RK4',f26,(0,2),(0,2),[('RK4 reference',rk(f26,0,2,1,4000)),('Euler h=0.01',euler(f26,0,1,.01,200))])
v27=euler(lambda t,q:12-4*q,0,0,.1,5)[-1][1]
add(27,'직렬 저항–축전기 회로에서 '+M(r'R=5,\ C=0.05,\ E=60,\quad RQ^{\prime}+Q/C=E')+'. (a) 방향장, (b) 극한 전하, (c) 평형해, (d) 영 초기전하의 해곡선, (e) '+M(r'h=0.1')+'로 반 초 뒤 전하를 구하라.','For a resistor-capacitor circuit, '+M(r'R=5,\ C=0.05,\ E=60,\quad RQ^{\prime}+Q/C=E')+'. Find (a) the field, (b) limiting charge, (c) equilibrium, (d) the solution from zero charge, and (e) its half-second Euler estimate with '+M(r'h=0.1')+'.',[(M(r'Q^{\prime}=12-4Q,\quad Q(t)=3(1-e^{-4t})')+'이므로 높이 삼 아래에서는 증가하고 위에서는 감소한다.',M(r'Q^{\prime}=12-4Q,\quad Q(t)=3(1-e^{-4t})')+' increases below height three and decreases above it.'),(M(r'Q_{n+1}=0.6Q_n+1.2,\quad Q_0=0')+'을 다섯 번 갱신한다.',M(r'Q_{n+1}=0.6Q_n+1.2,\quad Q_0=0')+' is updated five times.')],M(rf'Q_{{eq}}=\lim_{{t\to\infty}}Q(t)=3\ {{\rm C}};\quad Q_E(0.5)={v27:.5f}\ {{\rm C}}'),M(rf'Q_{{eq}}=\lim_{{t\to\infty}}Q(t)=3\ {{\rm C}};\quad Q_E(0.5)={v27:.5f}\ {{\rm C}}'),'정확한 반 초 값은 '+M(r'3(1-e^{-2})\approx2.593994')+'으로 오일러 값보다 작다.','The exact half-second charge '+M(r'3(1-e^{-2})\approx2.593994')+' is smaller than the Euler estimate.','abcde')
svg(27,'RC charging: Q prime = 12-4Q',lambda t,q:12-4*q,(0,1),(0,4),[('Q=3(1-exp(-4t))',sampled(lambda t:3*(1-math.exp(-4*t)),0,1)),('equilibrium Q=3',sampled(lambda t:3,0,1)),('Euler h=0.1',euler(lambda t,q:12-4*q,0,0,.1,10))])
v28=euler(lambda t,T:-.02*(T-20),0,95,2,5)[-1][1]
add(28,'초기 구십오 도의 커피를 이십 도 방에 둔다. 칠십 도에서 분당 일 도씩 식는다. (a) 냉각식을 정하고 (b) 방향장과 초기값 해 및 극한을 구하며 (c) '+M(r'h=2')+'로 십 분 뒤 온도를 근사하라.','Coffee begins at ninety-five degrees in a twenty-degree room and cools at one degree per minute when at seventy degrees. (a) Determine its equation; (b) plot the field and solution and give its limit; (c) estimate its ten-minute temperature with '+M(r'h=2')+'.',[(M(r'-1=-k(70-20)\Rightarrow k=0.02')+'.',M(r'-1=-k(70-20)\Rightarrow k=0.02')+'.'),(M(r'T^{\prime}=-0.02(T-20),\quad T(t)=20+75e^{-0.02t}')+'이다. 오일러 갱신은 '+M(r'T_{n+1}=0.96T_n+0.8')+'.',M(r'T^{\prime}=-0.02(T-20),\quad T(t)=20+75e^{-0.02t}')+'. Euler updates use '+M(r'T_{n+1}=0.96T_n+0.8')+'.')],M(rf'\lim_{{t\to\infty}}T(t)=20^\circ{{\rm C}};\quad T_E(10)={v28:.8f}^\circ{{\rm C}}'),M(rf'\lim_{{t\to\infty}}T(t)=20^\circ{{\rm C}};\quad T_E(10)={v28:.8f}^\circ{{\rm C}}'),'폐형식 오일러 값 '+M(r'20+75(0.96)^5')+'과 반복 계산이 일치한다.','The closed-form Euler value '+M(r'20+75(0.96)^5')+' agrees with iteration.','abc')
svg(28,'Coffee cooling; t in minutes',lambda t,T:-.02*(T-20),(0,100),(0,100),[('T=20+75 exp(-0.02t)',sampled(lambda t:20+75*math.exp(-.02*t),0,100)),('ambient T=20',sampled(lambda t:20,0,100)),('Euler first 10 min',euler(lambda t,T:-.02*(T-20),0,95,2,5))])
